import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"雾敛澄江","description":"","frontmatter":{"title":"雾敛澄江","date":"2026-11-20T00:00:00.000Z","seq":130,"categories":["美文","全宋词"],"collection":"《全宋词 · 柳永》","tags":["全宋词","宋"],"poem":true,"poem_quote":false,"author":"柳永","source_book":"全宋词","prev":{"text":"酒醒","link":"/blogs/全宋词·柳永/酒醒.html"},"next":{"text":"明月明月明月","link":"/blogs/全宋词·柳永/明月明月明月.html"}},"headers":[],"relativePath":"blogs/全宋词·柳永/雾敛澄江.md","filePath":"blogs/全宋词·柳永/雾敛澄江.md"}'),o={name:"blogs/全宋词·柳永/雾敛澄江.md"};function l(n,a,c,m,r,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="雾敛澄江" tabindex="-1">雾敛澄江 <a class="header-anchor" href="#雾敛澄江" aria-label="Permalink to &quot;雾敛澄江&quot;">​</a></h1><p class="poem-meta">宋 · 柳永　·　轮台子</p><div class="poem"><p class="poem-stanza">雾敛澄江，烟消蓝光碧。</p><p class="poem-stanza">彤霞衬遥天，掩映断续，半空残月。</p><p class="poem-stanza">孤村望处人寂寞，闻钓叟、甚处一声羌笛。</p><p class="poem-stanza">九疑山畔才雨过，斑竹作、血痕添色。</p><p class="poem-stanza">感行客。</p><p class="poem-stanza">翻思故国，恨因循阻隔。</p><p class="poem-stanza">路久沈消息。</p><p class="poem-stanza">正老松枯柏情如织。</p><p class="poem-stanza">闻野猿啼，愁听得。</p><p class="poem-stanza">见钓舟初出，芙蓉渡头，鸳鸯滩侧。</p><p class="poem-stanza">干名利禄终无益。</p><p class="poem-stanza">念岁岁间阻，迢迢紫陌。</p><p class="poem-stanza">翠蛾娇艳，从别后经今，花开柳拆伤魂魄。</p><p class="poem-stanza">利名牵役。</p><p class="poem-stanza">又争忍、把光景抛掷。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
